// 150 additional executable abilities. Every entry has its own mechanic and help text.
// Imported packs store IDs and recipe parameters, never executable handlers.
const NEW_ABILITIES={};
function ability(id,name,group,help,run){if(ATTACKS[id]||NEW_ABILITIES[id])throw Error('Duplicate ability '+id);NEW_ABILITIES[id]={name,group,help,run};}
const alive=()=>battle.entities.filter(e=>!e.dead);
const distance=(a,b)=>Math.hypot(a.x-b.x,(a.row-b.row)*500/battle.w.rows);
const nearFoes=(e,r=900)=>alive().filter(t=>t.side!==e.side&&distance(e,t)<=r).sort((a,b)=>Number(b.status.mark>battle.time)-Number(a.status.mark>battle.time)||distance(e,a)-distance(e,b));
const nearAllies=(e,r=900)=>alive().filter(t=>t.side===e.side&&distance(e,t)<=r);
const lowAlly=(e,r)=>nearAllies(e,r).filter(t=>t!==e&&!t.u.traits.includes('platform')).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];
function later(delay,fn){battle.tasks??=[];if(battle.tasks.length<240)battle.tasks.push({at:battle.time+delay,fn});}
function flash(e,text,color='#d6ff99'){effect(e.x,e.row,text,color);}
function hit(t,n,e,a){if(t&&!t.dead)damage(t,Math.max(0,n),e,a);}
function pure(t,n,e){if(!t||t.dead)return;t.hp-=Math.max(0,n);t.lastAttacker=e;if(t.hp<=0)kill(t);}
function timed(e,key,duration,value=true){e[key]=value;later(duration,()=>{e[key]=false;});}
function standable(u,row,col,ignore=[]){if(row<0||row>=battle.w.rows||col<0||col>=battle.w.cols)return false;const hidden=[];for(const e of ignore){hidden.push([e,e.dead]);e.dead=true;}const okay=canPlace(u,row,col,false);for(const [e,v] of hidden)e.dead=v;return okay;}
function placeNear(u,row,col){if(!u)return null;if(u.side==='zombie'){if(!compatibleRows(u,battle.w).includes(row))return null;return spawnEntity(u,Math.max(50,Math.min(920,cellX(col))),row);}for(let delta=0;delta<battle.w.cols;delta++)for(const c of delta===0?[col]:[col-delta,col+delta])if(standable(u,row,c))return spawnEntity(u,cellX(c),row,c);return null;}
function templateFor(e,a){return [...project.plants,...project.zombies].find(u=>u.id===a.target&&u.side===e.side);}
function cloneUnit(e,opts={}){const u=clone(e.u);u.hp=opts.hp||Math.max(1,e.maxHp*.35);u.attacks=u.attacks.filter(a=>!['splitOnDeath','revenant','phoenixAlly','resurrection','cloneNeighbor','broodNest'].includes(a.type));u.placement=opts.any?'any':u.placement;u.traits=u.traits.filter(t=>!['deathSpawn','platform'].includes(t));u.scale=Math.max(.3,u.scale*(opts.scale||.8));return u;}
function setCell(row,col,type,seconds=6){const i=row*battle.w.cols+col;if(i<0||i>=battle.w.tiles.length)return;const old=battle.w.tiles[i];battle.w.tiles[i]=type;paintBattleTiles();later(seconds,()=>{if(battle.w.tiles[i]===type){battle.w.tiles[i]=old;paintBattleTiles();}});}
function paintBattleTiles(){$$('.battleTile').forEach((el,i)=>el.className='battleTile '+battle.w.tiles[i]);}
function tileIndex(e){return e.row*battle.w.cols+Math.max(0,Math.min(battle.w.cols-1,Math.floor(e.x/900*battle.w.cols)));}
function buffWeather(type,duration=8){ensureNewState();battle.weatherBase??={...battle.weather};battle.weatherOverrides??=[];battle.weatherOverrides.push({type,intensity:1,effects:true,until:battle.time+duration});battle.weather={type,intensity:1,effects:true};}
function shootNew(e,a,d,kind,row=e.row){const n=battle.bullets.length;makeBullet(e,{...a,type:'shot'},d,row,e.side==='plant'?1:-1);if(battle.bullets.length===n)return null;const p=battle.bullets.at(-1);p.newKind=kind;p.originalAbility=a.type;p.ability=clone(a);p.roof=false;return p;}
function blast(e,a,x,row,d,r=110,friendly=false){const targets=alive().filter(t=>(friendly||t.side!==e.side)&&Math.hypot(t.x-x,(t.row-row)*500/battle.w.rows)<=r);targets.forEach(t=>hit(t,d,e,a));effect(x,row,'✹','#ffc56f');return targets.length;}
function newestDeath(side){const list=battle.fallen||[];return [...list].reverse().find(d=>d.side===side&&!d.used);}
function turnSide(t,side,seconds){if(!t||t.dead||t.charmOriginal)return false;t.charmOriginal=t.side;t.side=side;t.supportId=null;if(side==='plant')t.col=Math.min(battle.w.cols-1,Math.max(0,Math.floor(t.x/900*battle.w.cols)));later(seconds,()=>{if(!t.dead){t.side=t.charmOriginal;delete t.charmOriginal;}});return true;}

// 1–10: projectile mechanics.
ability('chargedLance','Charged lance','Projectiles','A projectile gains damage for every second spent in flight.',({e,a,d})=>!!shootNew(e,a,d,'charge'));
ability('orbitSeeds','Orbiting seeds','Projectiles','Count seeds orbit the caster for one second, then home toward enemies.',({e,a,d})=>{for(let i=0;i<Math.max(2,a.count);i++){const p=shootNew(e,a,d,'orbit');if(p)p.orbitAngle=i*Math.PI*2/Math.max(2,a.count);}return true;});
ability('returningHeal','Returning sap','Projectiles','A shot hits once, returns to its living caster, and heals it for the damage amount.',({e,a,d})=>!!shootNew(e,a,d,'returnHeal'));
ability('gravityOrb','Gravity orb','Projectiles','A moving orb drags enemies within 90 pixels toward itself before impact.',({e,a,d})=>!!shootNew(e,a,d,'gravity'));
ability('weavingShot','Weaving vine shot','Projectiles','A projectile weaves vertically between neighboring lanes as it crosses the board.',({e,a,d})=>!!shootNew(e,a,d,'weave'));
ability('acceleratingBolt','Accelerating bolt','Projectiles','Starts slowly and continuously accelerates; later impacts deal a momentum bonus.',({e,a,d})=>{const p=shootNew(e,a,d,'accelerate');if(p)p.speed=80;return !!p;});
ability('drillingCharge','Drilling shot','Projectiles','Pierces without a fixed hit count, losing speed and damage after each new enemy.',({e,a,d})=>!!shootNew(e,a,d,'drill'));
ability('relayBolt','Ally relay bolt','Projectiles','Flies to a forward ally first, then relaunches from that ally with a damage bonus.',({e,a,d,allies,dir})=>{const relay=allies.filter(t=>t!==e&&(t.x-e.x)*dir>20).sort((x,y)=>distance(e,x)-distance(e,y))[0];if(!relay)return false;const p=shootNew(e,a,d,'relay');if(p)p.relay=relay;return !!p;});
ability('timedCluster','Airburst cluster','Projectiles','Ignores contact, then bursts after 0.8 seconds into a local explosion.',({e,a,d})=>!!shootNew(e,a,d,'cluster'));
ability('seedMineLauncher','Trap seed launcher','Projectiles','Lobs a seed to the nearest target location, then leaves a damaging ground trap.',({e,a,d,t})=>{if(!t)return false;const p=shootNew(e,a,d,'trapSeed');if(p){p.destination={x:t.x,row:t.row};p.flight=.9;}return !!p;});

// 11–20: tactical target selection.
ability('mirrorHealth','Health-gap strike','Targeting','Damage increases with the difference between target and caster health percentages.',({e,a,d,t})=>{if(!t)return false;hit(t,d*(1+Math.abs(t.hp/t.maxHp-e.hp/e.maxHp)*4),e,a);return true;});
ability('bastionHunter','Bastion hunter','Targeting','Selects the most protected enemy; shield and armor value increase the hit.',({e,a,d,foes})=>{const t=foes.sort((x,y)=>(y.shieldHP||0)+y.u.armor*500-((x.shieldHP||0)+x.u.armor*500))[0];if(!t)return false;hit(t,d+(t.shieldHP||0)*.2+t.u.armor*d,e,a);return true;});
ability('rearAmbush','Rear ambush','Targeting','Strikes the rearmost enemy in range and pushes it toward the front of its horde.',({e,a,d,foes,dir})=>{const t=foes.sort((x,y)=>(y.x-x.x)*dir)[0];if(!t)return false;hit(t,d,e,a);if(!(t.anchorUntil>battle.time))t.x-=dir*35;return true;});
ability('lanePressure','Crowd lane barrage','Targeting','Finds the most crowded lane and divides a fixed damage budget among its enemies.',({e,a,d,foes})=>{const counts=Array(battle.w.rows).fill(0);foes.forEach(t=>counts[t.row]++);const row=counts.indexOf(Math.max(...counts)),ts=foes.filter(t=>t.row===row);if(!ts.length)return false;ts.forEach(t=>hit(t,d*3/ts.length,e,a));return true;});
ability('lonelyHunter','Isolation hunter','Targeting','Hits an isolated enemy for triple damage; clustered enemies receive a normal hit.',({e,a,d,foes})=>{const isolated=foes.find(t=>!foes.some(o=>o!==t&&distance(t,o)<120)),t=isolated||foes[0];if(!t)return false;hit(t,d*(isolated?3:1),e,a);return true;});
ability('swarmPunish','Crowd compression','Targeting','The nearest enemy takes more damage for each other enemy clustered around it.',({e,a,d,t,foes})=>{if(!t)return false;hit(t,d*(1+foes.filter(o=>o!==t&&distance(t,o)<120).length),e,a);return true;});
ability('revengeShot','Retaliation memory','Targeting','Returns damage to the last attacker, adding half of the damage recently received.',({e,a,d})=>{const t=e.lastAttacker;if(!t||t.dead||t.side===e.side)return false;hit(t,d+(e.recentPain||0)*.5,e,a);e.recentPain=0;return true;});
ability('medicHunter','Medic hunter','Targeting','Targets a healer first and silences its healing abilities for five seconds.',({e,a,d,foes})=>{const t=foes.find(t=>t.u.attacks.some(a=>['heal','proximityHeal','rescue','emergencyMend','deathHeal'].includes(a.type)));if(!t)return false;t.status.silence=battle.time+5;hit(t,d,e,a);return true;});
ability('moverIntercept','Movement intercept','Targeting','Predicts the nearest enemy’s position 0.7 seconds ahead and strikes that location.',({e,a,d,t})=>{if(!t)return false;const x=t.x+(t.side==='zombie'?-1:1)*t.u.speed*.7,row=t.row;later(.7,()=>blast(e,a,x,row,d,70));effect(x,row,'⌖');return true;});
ability('focusRamp','Unbroken focus','Targeting','Consecutive hits on the same living enemy build a bonus; changing targets resets it.',({e,a,d,t})=>{if(!t)return false;e.focusCount=e.focusId===t.id?Math.min(8,(e.focusCount||0)+1):1;e.focusId=t.id;hit(t,d*(1+e.focusCount*.2),e,a);return true;});

// 21–30: control and enemy intent.
ability('sleepUntilHit','Sleep spore','Control','Puts the nearest enemy to sleep for up to eight seconds; taking damage wakes it.',({t})=>{if(!t)return false;t.sleepUntil=battle.time+8;return true;});
ability('tetherPair','Twin tether','Control','Links two enemies for six seconds: damage to either echoes to the other.',({foes})=>{if(foes.length<2)return false;foes[0].tether=foes[1];foes[1].tether=foes[0];foes[0].tetherUntil=foes[1].tetherUntil=battle.time+6;return true;});
ability('gravityWell','Stationary gravity well','Control','Creates a four-second vortex at the target; it continually draws nearby foes inward.',({e,a,d,t})=>{if(!t)return false;battle.newZones.push({type:'vortex',x:t.x,row:t.row,until:battle.time+4,source:e,a,amount:d,radius:160});return true;});
ability('laneSeal','Lane seal','Control','Prevents nearby enemies from changing lanes for six seconds, without stopping their advance.',({foes})=>{if(!foes.length)return false;foes.forEach(t=>t.laneSealUntil=battle.time+6);return true;});
ability('fearReverse','Panic retreat','Control','Makes a target walk backward for three seconds, then resume its original direction.',({t})=>{if(!t||t.anchorUntil>battle.time)return false;t.fearUntil=battle.time+3;return true;});
ability('tauntCall','Taunting call','Control','Forces nearby ranged and special attackers to prioritize this caster for five seconds.',({e,foes})=>{if(!foes.length)return false;foes.forEach(t=>{t.forcedTarget=e;t.tauntUntil=battle.time+5;});return true;});
ability('swapSides','Temporary hypnosis','Control','Temporarily changes one enemy’s allegiance for five seconds, then restores it.',({e,t})=>turnSide(t,e.side,5));
ability('disarmShots','Projectile disarm','Control','Disables ranged projectile recipes for five seconds while leaving melee and support available.',({t})=>{if(!t)return false;t.disarmUntil=battle.time+5;return true;});
ability('confusion','Confusion seed','Control','The target’s next offensive action hits its own nearest ally instead.',({t})=>{if(!t)return false;t.confused=true;return true;});
ability('fatigue','Exhausting pollen','Control','Each attack made by the target over six seconds further slows its next recharge.',({t})=>{if(!t)return false;t.fatigueUntil=battle.time+6;t.fatigueDebt=0;return true;});

// 31–40: tile interaction.
ability('seedBridge','Temporary land bridge','Terrain','Turns water under the caster and one tile ahead into grass for eight seconds.',({e,dir})=>{let changed=false;const c=Math.max(0,Math.min(battle.w.cols-1,Math.floor(e.x/900*battle.w.cols)));for(const col of [c,c+dir])if(col>=0&&col<battle.w.cols&&tileAt(e.row,col)==='water'){setCell(e.row,col,'grass',8);changed=true;}return changed;});
ability('roofRamp','Roof firing ramp','Terrain','Builds a ramp on the caster’s roof tile; normal shots clear the slope for eight seconds.',({e})=>{const i=tileIndex(e);if(battle.w.tiles[i]!=='roof')return false;battle.tileFlags[i]={...(battle.tileFlags[i]||{}),rampUntil:battle.time+8};return true;});
ability('quarantineTile','Quarantine tile','Terrain','The target’s tile blocks planting and silences occupants for five seconds.',({t})=>{if(!t)return false;const i=tileIndex(t);setCell(t.row,i%battle.w.cols,'blocked',5);battle.tileFlags[i]={...(battle.tileFlags[i]||{}),quarantineUntil:battle.time+5};return true;});
ability('fertileSoil','Fertile planting soil','Terrain','Marks the caster’s tile and neighbors: each newly planted unit there grants bonus sun.',({e,a,d})=>{const c=tileIndex(e)%battle.w.cols;for(const col of [c-1,c,c+1])if(col>=0&&col<battle.w.cols)battle.tileFlags[e.row*battle.w.cols+col]={fertileUntil:battle.time+8,value:d};return true;});
ability('landmineChain','Chained tile mines','Terrain','Arms Count adjacent tiles; an enemy entering one detonates every connected armed tile.',({e,a,d,dir})=>{const c=tileIndex(e)%battle.w.cols,chain=uid();for(let j=0;j<a.count;j++){const col=c+dir*j;if(col>=0&&col<battle.w.cols)battle.tileFlags[e.row*battle.w.cols+col]={mine:{chain,side:e.side,source:e,a,damage:d,until:battle.time+15}};}return true;});
ability('conveyorTile','Conveyor launch tile','Terrain','Gives allies occupying the caster’s tile a one-cell rightward ride over one second.',({e,allies})=>{const i=tileIndex(e),ts=allies.filter(t=>tileIndex(t)===i&&!t.u.traits.includes('platform'));if(!ts.length)return false;ts.forEach(t=>{t.forcedMotion={until:battle.time+1,vx:900/battle.w.cols};});return true;});
ability('sprinkler','Healing sprinkler','Terrain','An eight-second sprinkler heals nearby plants and extinguishes burn on either side.',({e,a,d})=>{battle.newZones.push({type:'sprinkler',x:e.x,row:e.row,source:e,a,amount:d,radius:135,until:battle.time+8});return true;});
ability('brittleIce','Brittle ice patch','Terrain','Freezes the target tile; the first grounded enemy to enter slips, then the ice shatters.',({t})=>{if(!t)return false;const i=tileIndex(t);setCell(t.row,i%battle.w.cols,'ice',10);battle.tileFlags[i]={brittleUntil:battle.time+10};return true;});
ability('sunWell','Sun-amplifying well','Terrain','Sun tokens near this tile have their value doubled once, for eight seconds.',({e})=>{battle.tileFlags[tileIndex(e)]={sunWellUntil:battle.time+8};return true;});
ability('laneGate','One-use lane gate','Terrain','Arms a tile to send the next enemy occupant to a compatible adjacent lane.',({e})=>{battle.tileFlags[tileIndex(e)]={gate:{side:e.side,until:battle.time+12}};return true;});

// 41–50: economy and spending.
ability('investment','Sun investment','Economy','Invests 50 sun now; returns 50 plus Amount after eight seconds if the caster survives.',({e,d})=>{if(battle.sun<50)return false;battle.sun-=50;later(8,()=>{if(!e.dead)battle.sun+=50+d;});return true;});
ability('bountyMark','Bounty contract','Economy','Marks an enemy; its eventual death pays Amount sun once.',({t,d})=>{if(!t)return false;t.bounty=(t.bounty||0)+d;return true;});
ability('healthForSun','Health-to-sun trade','Economy','Sacrifices up to Amount health, never the last point, and gains 1.5 sun per health lost.',({e,d})=>{const paid=Math.min(d,e.hp-1);if(paid<=0)return false;e.hp-=paid;battle.sun+=Math.floor(paid*1.5);return true;});
ability('sunForShield','Purchased shields','Economy','Spends up to Amount banked sun and divides twice that value into nearby allied shields.',({allies,d})=>{const paid=Math.min(d,battle.sun);if(!paid||!allies.length)return false;battle.sun-=paid;allies.forEach(t=>{t.shieldHP=paid*2/allies.length;t.shieldUntil=battle.time+8;});return true;});
ability('refundNextPlant','Next-purchase rebate','Economy','The next paid planting refunds up to Amount of its actual sun cost.',({d})=>{battle.purchaseRebate=Math.max(battle.purchaseRebate||0,d);return true;});
ability('sunCompost','Sun compost','Economy','Consumes soon-expiring sun tokens and converts their value into healing for nearby allies.',({e,allies,a})=>{const suns=battle.suns.filter(s=>s.until-battle.time<5&&Math.hypot(s.x-e.x,s.y-rowY(e.row))<a.range);if(!suns.length||!allies.length)return false;const n=suns.reduce((v,s)=>v+s.value,0)/allies.length,ids=new Set(suns.map(s=>s.id));battle.suns=battle.suns.filter(s=>!ids.has(s.id));allies.forEach(t=>t.hp=Math.min(t.maxHp,t.hp+n));return true;});
ability('waveDividend','Next-wave dividend','Economy','Places a one-time Amount-sun reward on the next wave transition.',({e,d})=>{if(e.dividendWave)return false;e.dividendWave=battle.wave+1;e.dividendAmount=d;return true;});
ability('bankInterest','Bank interest','Economy','While enemies are present, earns 10% of the bank, capped at Amount sun per activation.',({d,foes})=>{if(!foes.length||battle.sun<=0)return false;battle.sun+=Math.min(d,Math.floor(battle.sun*.1));return true;});
ability('sunTax','Planting tax','Economy','The next paid planting loses up to Amount additional banked sun.',({d})=>{battle.purchaseTax=Math.max(battle.purchaseTax||0,d);return true;});
ability('emergencyCredit','Emergency sun credit','Economy','Once per caster, grants Amount sun if the bank is empty and an enemy is near the house.',({e,d,foes})=>{if(e.creditUsed||battle.sun>0||!foes.some(t=>t.x<225))return false;e.creditUsed=true;battle.sun+=d;return true;});

// 51–60: team support.
ability('damageLink','Shared-pain link','Support','Links the weakest ally to the caster: half of the ally’s damage is redirected to the caster.',({e,friend})=>{if(!friend)return false;friend.painGuard=e;friend.painGuardUntil=battle.time+6;return true;});
ability('healthEqualize','Health equalizer','Support','Redistributes existing allied health so everyone has the same health percentage.',({allies})=>{if(allies.length<2)return false;const total=allies.reduce((n,t)=>n+t.hp,0),max=allies.reduce((n,t)=>n+t.maxHp,0);allies.forEach(t=>t.hp=Math.max(1,t.maxHp*total/max));return true;});
ability('rotateCooldown','Cooldown exchange','Support','Swaps the shortest and longest current attack timers among nearby allies.',({allies})=>{const slots=allies.flatMap(e=>e.timers.map((t,i)=>({e,i,t}))).sort((a,b)=>a.t-b.t);if(slots.length<2)return false;const a=slots[0],b=slots.at(-1);[a.e.timers[a.i],b.e.timers[b.i]]=[b.t,a.t];return true;});
ability('accelerateSun','Sun-generator accelerator','Support','Advances only the sun-production timers of other allied producers by Amount seconds.',({e,allies,d})=>{let okay=false;for(const t of allies)if(t!==e)t.u.attacks.forEach((a,i)=>{if(a.type==='sun'){t.timers[i]=Math.max(0,t.timers[i]-d);okay=true;}});return okay;});
ability('armorPolish','Restorative shield polish','Support','For six seconds, shield absorption also heals its owner for half the amount absorbed.',({allies})=>{allies.forEach(t=>t.polishUntil=battle.time+6);return !!allies.length;});
ability('attackEcho','Ally attack echo','Support','The nearest other ally repeats its next offensive recipe once at half strength.',({e,allies})=>{const t=allies.find(t=>t!==e&&t.u.attacks.length);if(!t)return false;t.echoCharge=true;return true;});
ability('weaponLoan','Loaned weapon power','Support','Loans Amount bonus attack damage to the weakest ally for six seconds.',({friend,d})=>{if(!friend)return false;friend.loanDamage=d;friend.loanUntil=battle.time+6;return true;});
ability('overhealBank','Overheal reservoir','Support','Heals nearby allies by Amount; excess becomes a temporary shield instead of being wasted.',({allies,d})=>{for(const t of allies){const overflow=Math.max(0,t.hp+d-t.maxHp);t.hp=Math.min(t.maxHp,t.hp+d);t.shieldHP=(t.shieldUntil>battle.time?t.shieldHP:0)+overflow;t.shieldUntil=battle.time+8;}return !!allies.length;});
ability('rallyOnKill','Kill-triggered rally','Support','For eight seconds, each nearby enemy death advances allied attack timers by two seconds.',({e,a})=>{e.rallyUntil=battle.time+8;e.rallyRange=a.range;return true;});
ability('emergencyMend','Critical-care shelter','Support','Only heals allies below 25% health and briefly makes them immune to damage.',({allies,d})=>{const ts=allies.filter(t=>t.hp/t.maxHp<.25);ts.forEach(t=>{t.hp=Math.min(t.maxHp,t.hp+d);t.immuneUntil=battle.time+1;});return !!ts.length;});

// 61–70: damage response.
ability('thornArmor','Retaliating thorn armor','Defense','For six seconds, reflects half of nearby contact damage back to its attacker.',({e})=>{e.thornsUntil=battle.time+6;return true;});
ability('projectileNet','Projectile-catching net','Defense','Arms Count charges that destroy incoming enemy projectiles within 100 pixels.',({e,a})=>{e.netCharges=Math.max(1,a.count);e.netUntil=battle.time+8;return true;});
ability('directionalShield','Directional projectile guard','Defense','For five seconds, blocks projectile hits arriving from the front; melee can pass through.',({e})=>{e.frontShieldUntil=battle.time+5;return true;});
ability('lastStand','One-use last stand','Defense','Once per caster, a lethal hit leaves one health and grants 1.5 seconds of immunity.',({e})=>{if(e.lastStandSpent)return false;e.lastStandArmed=true;return true;});
ability('damageCap','Per-hit damage cap','Defense','For five seconds, no single incoming hit can exceed 10% of maximum health.',({e})=>{e.capUntil=battle.time+5;return true;});
ability('delayedPain','Deferred pain','Defense','For five seconds, delays half of incoming damage by four seconds.',({e})=>{e.delayPainUntil=battle.time+5;return true;});
ability('stoneForm','Stone form','Defense','Becomes immobile and unable to attack for four seconds, but takes 90% less damage.',({e})=>{e.stoneUntil=battle.time+4;return true;});
ability('phaseCycle','Pulsing phase cloak','Defense','For nine seconds, phases out during the first second of each three-second cycle.',({e})=>{e.phaseStart=battle.time;e.phaseUntil=battle.time+9;return true;});
ability('sacrificialGuard','Sacrificial bodyguard','Defense','Takes the weakest ally’s next damaging hit in full, then the protection ends.',({e,friend})=>{if(!friend)return false;friend.sacrificeGuard=e;return true;});
ability('adaptiveArmor','Adaptive armor','Defense','For eight seconds, repeated hits of the same recipe type build up to 60% extra resistance.',({e})=>{e.adaptUntil=battle.time+8;e.adaptType='';e.adaptStacks=0;return true;});

// 71–80: movement tactics.
ability('chargeContact','Contact charge','Movement','Charges forward for one second, striking the first enemy encountered and stunning itself afterward.',({e,d,a,dir})=>{e.contactCharge={until:battle.time+1.4,vx:dir*220,damage:d,a};return true;});
ability('hopOverAlly','Friendly obstacle hop','Movement','Hops past the nearest forward ally into a free, terrain-compatible location.',({e,allies,dir})=>{const t=allies.filter(t=>t!==e&&(t.x-e.x)*dir>0).sort((x,y)=>distance(e,x)-distance(e,y))[0];if(!t)return false;if(e.side==='zombie'){e.x=t.x-90;return true;}const c=Math.floor(t.x/900*battle.w.cols)+1;if(standable(e.u,e.row,c,[e])){e.x=cellX(c);e.col=c;e.supportId=null;return true;}return false;});
ability('orbitAnchor','Ally orbit patrol','Movement','Patrols around a nearby ally through compatible adjacent rows for six seconds.',({e,allies})=>{const anchor=allies.find(t=>t!==e);if(!anchor)return false;e.orbitAnchor={target:anchor,until:battle.time+6,next:battle.time};return true;});
ability('retreatAtLow','Healing retreat','Movement','Below half health, retreats for three seconds while regenerating Amount health per second.',({e,d,dir})=>{if(e.hp>=e.maxHp*.5)return false;e.retreat={until:battle.time+3,vx:-dir*60,heal:d};return true;});
ability('lanePursuit','Weak-target pursuit','Movement','Moves to the lane of the weakest enemy, provided the destination supports this unit.',({e,foes})=>{const t=foes.sort((x,y)=>x.hp/x.maxHp-y.hp/y.maxHp)[0];return !!t&&reposition(e,t.row,Math.max(0,e.col));});
ability('swapWithAlly','Friendly position exchange','Movement','Exchanges positions with the frontmost nearby ally; terrain is checked for both.',({e,allies,dir})=>{const t=allies.filter(t=>t!==e).sort((x,y)=>(y.x-x.x)*dir)[0];if(!t)return false;return exchangePositions(e,t);});
ability('pullAlly','Ally towline','Movement','Pulls an injured ally toward the caster’s rear, stopping at an available valid tile.',({e,friend,dir,d})=>{if(!friend)return false;if(friend.side==='zombie'){friend.x=Math.min(920,e.x+Math.max(40,d));return true;}return moveToAvailable(friend,friend.row,Math.max(0,Math.floor((e.x-dir*70)/900*battle.w.cols)));});
ability('shoveLine','Friendly formation push','Movement','Pushes each nearby ally behind the caster forward by one valid tile, frontmost first.',({e,allies,dir})=>{let moved=false;for(const t of allies.filter(t=>t!==e&&(t.x-e.x)*dir<0).sort((a,b)=>(b.x-a.x)*dir)){if(t.side==='zombie'){t.x-=60;moved=true;}else moved=moveToAvailable(t,t.row,t.col+1)||moved;}return moved;});
ability('dashThrough','Piercing dash','Movement','Dashes through up to Count enemies in its lane, damaging each, and ends beyond them.',({e,a,d,foes,dir})=>{const ts=foes.filter(t=>t.row===e.row&&(t.x-e.x)*dir>0).slice(0,a.count);if(!ts.length)return false;ts.forEach(t=>hit(t,d,e,a));const x=ts.at(-1).x+dir*75;if(e.side==='zombie')e.x=Math.max(20,x);else moveToAvailable(e,e.row,Math.min(battle.w.cols-1,Math.floor(x/900*battle.w.cols)));return true;});
ability('anchorBoots','Anchored roots','Movement','For eight seconds, resists knockback, forced lane changes, gravity and fear.',({e})=>{e.anchorUntil=battle.time+8;e.fearUntil=0;e.laneSealUntil=Math.max(e.laneSealUntil||0,battle.time+8);return true;});

// 81–90: spawning and conversion.
ability('splitOnDeath','Splitting offspring','Summoning','Arms a one-time death split into Count small copies with reduced health and no splitting recipe.',({e,a})=>{e.splitChildren=Math.max(1,a.count);return true;});
ability('decoy','Temporary decoy','Summoning','Creates a low-health, nonattacking decoy that taunts enemies and expires after six seconds.',({e,d,a})=>{const u=cloneUnit(e,{hp:Math.max(10,d),scale:.75,any:true});u.attacks=[];u.speed=0;const n=placeNear(u,e.row,Math.max(0,e.col+1));if(!n)return false;n.expires=battle.time+6;n.decoy=true;nearFoes(n,a.range).forEach(t=>{t.forcedTarget=n;t.tauntUntil=battle.time+6;});return true;});
ability('cloneNeighbor','Short-lived ally clone','Summoning','Copies the nearest other ally at reduced health; the clone expires after eight seconds.',({e,allies})=>{const t=allies.find(t=>t!==e&&!t.decoy);if(!t)return false;const n=placeNear(cloneUnit(t),e.row,Math.max(0,e.col+1));if(n)n.expires=battle.time+8;return !!n;});
ability('hatchling','Delayed hatchling','Summoning','An egg hatches into the selected target template after four seconds, even if the caster dies.',({e,a})=>{const u=templateFor(e,a);if(!u)return false;const row=e.row,col=Math.max(0,e.col+1);later(4,()=>placeNear(u,row,col));flash(e,'EGG');return true;});
ability('swarmDrones','Temporary attack drones','Summoning','Summons up to three tiny, short-lived shooters using the caster’s artwork.',({e,a,d})=>{for(let i=0;i<Math.min(3,a.count);i++){const u=cloneUnit(e,{hp:25,scale:.5,any:true});u.attacks=[attack('shot',Math.max(1,d*.4),1)];u.traits=['flying'];const n=placeNear(u,Math.min(battle.w.rows-1,e.row+i),Math.max(0,e.col+1));if(n)n.expires=battle.time+8;}return true;});
ability('summonBehind','Ambush summon','Summoning','Places the selected allied template behind the nearest enemy, where terrain permits.',({e,a,t})=>{const u=templateFor(e,a);if(!u||!t)return false;return !!placeNear(u,t.row,Math.min(battle.w.cols-1,Math.max(0,Math.floor(t.x/900*battle.w.cols)+(e.side==='plant'?1:-1))));});
ability('mergeMinions','Minion fusion','Summoning','Consumes the two weakest nearby allies to create the selected template with their combined health.',({e,a,allies})=>{const u=templateFor(e,a),ts=allies.filter(t=>t!==e&&!t.u.traits.includes('platform')).sort((a,b)=>a.hp-b.hp).slice(0,2);if(!u||ts.length<2)return false;const hp=ts.reduce((n,t)=>n+t.hp,0),row=ts[0].row,col=Math.max(0,ts[0].col);ts.forEach(t=>kill(t,false));const n=placeNear(u,row,col);if(n)n.hp=n.maxHp=Math.max(u.hp,hp);return !!n;});
ability('resurrection','Fallen-ally resurrection','Summoning','Revives the most recently fallen ally at half health; each fallen record can be used once.',({e})=>{const f=newestDeath(e.side);if(!f)return false;const u=clone(f.u);u.hp=Math.max(1,u.hp*.5);const n=placeNear(u,f.row,Math.max(0,f.col));if(n)f.used=true;return !!n;});
ability('possession','Permanent possession','Summoning','Consumes a wounded enemy below 30% health and replaces it with an allied copy.',({e,t})=>{if(!t||t.hp/t.maxHp>.3)return false;const u=cloneUnit(t,{any:true});u.side=e.side;u.traits=u.traits.filter(t=>!['platform','deathSpawn'].includes(t));const row=t.row,col=Math.max(0,Math.min(battle.w.cols-1,Math.floor(t.x/900*battle.w.cols)));kill(t);return !!placeNear(u,row,col);});
ability('broodNest','Reactive brood nest','Summoning','The next three damaging hits to this caster each release a selected allied hatchling.',({e,a})=>{const u=templateFor(e,a);if(!u)return false;e.brood={u:clone(u),charges:3};return true;});

// 91–100: life and death.
ability('deathNova','Death nova','Lifecycle','Arms an Amount-damage blast around this unit when it dies.',({e,a,d})=>{e.deathNova={a:clone(a),damage:d,range:Math.min(250,a.range)};return true;});
ability('deathHeal','Final healing gift','Lifecycle','When this unit dies, nearby surviving allies recover Amount health.',({e,a,d})=>{e.deathHeal={amount:d,range:a.range};return true;});
ability('deathSun','Final sun bloom','Lifecycle','When this unit dies, it leaves Count collectible sun tokens worth Amount each.',({e,a,d})=>{e.deathSun={amount:d,count:a.count};return true;});
ability('revenant','One-use revenant','Lifecycle','Once per unit, death instead restores half health and stuns it for two seconds.',({e})=>{if(e.revenantSpent)return false;e.revenantArmed=true;return true;});
ability('timedRebirth','Timed rebirth','Lifecycle','Temporarily removes this unit and restores it three seconds later at full template health.',({e})=>{const u=clone(e.u),row=e.row,col=Math.max(0,e.col);u.attacks=u.attacks.filter(a=>a.type!=='timedRebirth');kill(e,false);later(3,()=>placeNear(u,row,col));return true;});
ability('healthDecayAura','Maximum-health erosion','Lifecycle','For four seconds, nearby enemies lose Amount maximum health per second without falling below one.',({e,a,d})=>{e.erosion={until:battle.time+4,range:a.range,amount:d};return true;});
ability('cocoon','Protective metamorphosis','Lifecycle','Cannot act for four seconds, then becomes the selected template with an extra Amount shield.',({e,a,d})=>{const u=templateFor(e,a);if(!u)return false;e.cocoonUntil=battle.time+4;e.shieldHP=d;e.shieldUntil=battle.time+5;later(4,()=>{if(!e.dead){e.u=clone(u);e.hp=e.maxHp=u.hp;e.timers=u.attacks.map(a=>a.interval);}});return true;});
ability('martyrBlast','Martyr transfer','Lifecycle','Sacrifices this caster and transfers its remaining health plus Amount as damage to the strongest enemy.',({e,a,d,foes})=>{const t=foes.sort((a,b)=>b.hp-a.hp)[0];if(!t)return false;const n=e.hp+d;kill(e);hit(t,n,e,a);return true;});
ability('soulHarvest','Soul-charged next strike','Lifecycle','For eight seconds, nearby enemy deaths each add Amount to the caster’s next offensive action.',({e,a,d})=>{e.harvest={until:battle.time+8,range:a.range,amount:d};return true;});
ability('phoenixAlly','Phoenix blessing','Lifecycle','Marks the weakest ally to survive one death at 35% health with one second of immunity.',({friend})=>{if(!friend||friend.phoenixSpent)return false;friend.phoenix=true;return true;});

// 101–110: environmental interaction.
ability('callRain','Summon rain','Weather','Creates eight seconds of rain and extinguishes every burning unit immediately.',()=>{buffWeather('rain');alive().forEach(e=>delete e.status.burn);return true;});
ability('callSnow','Preserving snowfall','Weather','Creates eight seconds of snow and extends every loose sun token’s lifetime by eight seconds.',()=>{buffWeather('snow');battle.suns.forEach(s=>s.until+=8);return true;});
ability('callWind','Wind front','Weather','Creates a wind front for eight seconds and clears stationary poison and burning zones.',()=>{buffWeather('wind');battle.zones=battle.zones.filter(z=>!['poisonCloud','fireTrail'].includes(z.type));return true;});
ability('clearSky','Break the clouds','Weather','Creates clear skies for eight seconds and allows sky sun even during a night gimmick.',()=>{buffWeather('clear');battle.clearSkyUntil=battle.time+8;return true;});
ability('lightningRod','Lightning collector','Weather','Collects storm strikes safely; the next activation discharges stored lightning into nearby enemies.',({e,a,foes})=>{e.lightningRodUntil=battle.time+10;const n=e.lightningCharge||0;if(n){foes.forEach(t=>hit(t,n/Math.max(1,foes.length),e,a));e.lightningCharge=0;}return true;});
ability('sunLens','Focused sunlight lens','Weather','Converts nearby loose sun tokens into fast projectiles whose damage equals their sun value.',({e,a})=>{const suns=battle.suns.filter(s=>Math.hypot(s.x-e.x,s.y-rowY(e.row))<a.range).slice(0,6);if(!suns.length)return false;for(const s of suns){const p=shootNew(e,a,s.value,'accelerate');if(p){p.x=s.x;p.y=s.y;}battle.suns=battle.suns.filter(x=>x!==s);}return true;});
ability('snowballRoll','Growing snowball','Weather','Rolls a ground projectile that gains size and damage with distance and slows enemies it hits.',({e,a,d})=>!!shootNew(e,{...a,mods:[...new Set([...a.mods,'slow'])]},d,'snowball'));
ability('puddleShock','Connected-water shock','Weather','Electrifies the connected pool containing the target; dry tiles break the connection.',({e,a,d,foes})=>{const t=foes.find(t=>battle.w.tiles[tileIndex(t)]==='water');if(!t)return false;const seen=connectedTiles(tileIndex(t),'water');foes.filter(t=>seen.has(tileIndex(t))).forEach(t=>hit(t,d,e,a));return true;});
ability('fogLantern','Fog-cutting lantern','Weather','Clears a visible circle in fog around this unit for ten seconds.',({e,a})=>{e.lanternUntil=battle.time+10;e.lanternRange=Math.min(300,a.range);return true;});
ability('hailShelter','Weatherproof shelter','Weather','For eight seconds, nearby allies ignore sourceless meteor and storm damage.',({allies})=>{allies.forEach(t=>t.weatherSafeUntil=battle.time+8);return !!allies.length;});

// 111–120: status combinations.
ability('ignitePoison','Ignite poison','Reactions','Consumes a poisoned enemy’s poison to trigger an explosion around it.',({e,a,d,foes})=>{const t=foes.find(t=>t.status.poison>battle.time);if(!t)return false;delete t.status.poison;blast(e,a,t.x,t.row,d*2,125);return true;});
ability('shatterFrozen','Ice shatter','Reactions','Consumes stun on a target for triple damage and sprays half damage to its neighbors.',({e,a,d,foes})=>{const t=foes.find(t=>t.status.stun>battle.time);if(!t)return false;delete t.status.stun;hit(t,d*3,e,a);foes.filter(o=>o!==t&&distance(o,t)<110).forEach(o=>hit(o,d*.5,e,a));return true;});
ability('steamBurst','Steam reaction','Reactions','A burning, slowed target loses both statuses and releases steam that stuns nearby foes.',({e,a,d,foes})=>{const t=foes.find(t=>t.status.burn>battle.time&&t.status.slow>battle.time);if(!t)return false;delete t.status.burn;delete t.status.slow;foes.filter(o=>distance(o,t)<150).forEach(o=>{o.status.stun=battle.time+1;hit(o,d,e,a);});return true;});
ability('toxinLeech','Toxin extraction','Reactions','Removes poison from one enemy; its remaining duration becomes caster healing plus a hit.',({e,a,d,foes})=>{const t=foes.find(t=>t.status.poison>battle.time);if(!t)return false;const n=(t.status.poison-battle.time)*7;delete t.status.poison;e.hp=Math.min(e.maxHp,e.hp+n);hit(t,d,e,a);return true;});
ability('conductiveMark','Conductive coating','Reactions','For six seconds, damage to this enemy arcs 25% of that damage to another nearby enemy.',({t})=>{if(!t)return false;t.conductiveUntil=battle.time+6;return true;});
ability('spreadAffliction','Contagion transfer','Reactions','Copies a target’s longest active harmful status to all other enemies within 140 pixels.',({foes})=>{const keys=['slow','poison','burn','stun','weaken','silence','root','curse'];for(const t of foes){const k=keys.sort((a,b)=>(t.status[b]||0)-(t.status[a]||0))[0];if(t.status[k]>battle.time){foes.filter(o=>o!==t&&distance(o,t)<140).forEach(o=>o.status[k]=t.status[k]);return true;}}return false;});
ability('purgeBuffs','Buff stripping','Reactions','Removes shields, reflection, buffs and frenzy, then suppresses rage bonuses for six seconds.',({t})=>{if(!t)return false;t.shieldHP=0;t.reflectUntil=0;t.buffUntil=0;delete t.status.frenzy;t.rageSuppressedUntil=battle.time+6;return true;});
ability('detonateMark','Marked-target detonation','Reactions','First activation marks an enemy. A later activation consumes that mark for triple damage.',({e,a,d,t})=>{if(!t)return false;if(t.status.mark>battle.time){delete t.status.mark;hit(t,d*3,e,a);}else t.status.mark=battle.time+8;return true;});
ability('freezeBurn','Thermal shock','Reactions','A burning target instantly loses 10% maximum health and is stunned; burn is consumed.',({e,foes})=>{const t=foes.find(t=>t.status.burn>battle.time);if(!t)return false;delete t.status.burn;pure(t,t.maxHp*.1,e);t.status.stun=battle.time+1.5;return true;});
ability('antidoteBurst','Antidote discharge','Reactions','Cures allied poison; each remaining second cured adds damage to a burst around the caster.',({e,a,d,allies})=>{let seconds=0;allies.forEach(t=>{seconds+=Math.max(0,(t.status.poison||0)-battle.time);delete t.status.poison;});if(!seconds)return false;blast(e,a,e.x,e.row,d+seconds*7,Math.min(250,a.range));return true;});

// 121–130: precision and reactive damage.
ability('shieldSnipe','Barrier-bypassing needle','Precision','Targets an enemy with a barrier and deals pure damage that ignores both shield and armor.',({e,d,foes})=>{const t=foes.find(t=>t.shieldHP>0&&t.shieldUntil>battle.time);if(!t)return false;pure(t,d,e);return true;});
ability('groundFault','Traveling ground fault','Precision','A ripple advances column by column, striking grounded enemies once in each column.',({e,a,d,dir})=>{for(let j=0;j<battle.w.cols;j++){const col=dir>0?j:battle.w.cols-1-j;later(j*.15,()=>alive().filter(t=>t.side!==e.side&&t.row===e.row&&tileIndex(t)%battle.w.cols===col&&!t.u.traits.includes('flying')).forEach(t=>hit(t,d,e,a)));}return true;});
ability('airNet','Grounding net','Precision','Temporarily removes a flying enemy’s flight trait so melee attacks and traps can reach it.',({foes})=>{const t=foes.find(t=>t.u.traits.includes('flying'));if(!t)return false;t.u.traits=t.u.traits.filter(k=>k!=='flying');later(6,()=>{if(!t.dead&&!t.u.traits.includes('flying'))t.u.traits.push('flying');});return true;});
ability('lineEqualizer','Health-gap equalizer','Precision','Reduces healthier enemies toward the weakest enemy’s current health, by at most Amount each.',({e,a,d,foes})=>{if(foes.length<2)return false;const low=Math.min(...foes.map(t=>t.hp));foes.filter(t=>t.hp>low).forEach(t=>hit(t,Math.min(d,t.hp-low),e,a));return true;});
ability('armorHarvest','Armor siphon','Precision','Steals up to Amount percentage points of enemy armor and permanently adds half to the caster.',({e,d,t})=>{if(!t||t.u.armor<=0)return false;const n=Math.min(t.u.armor,d/100);t.u.armor-=n;e.u.armor=Math.min(.9,e.u.armor+n*.5);return true;});
ability('healthSwap','Vitality exchange','Precision','Exchanges caster and target health percentages while preserving their own maximum health.',({e,t})=>{if(!t)return false;const a=e.hp/e.maxHp,b=t.hp/t.maxHp;e.hp=Math.max(1,e.maxHp*b);t.hp=Math.max(1,t.maxHp*a);return true;});
ability('momentumStrike','Traveled-distance strike','Precision','Adds damage equal to the distance this caster has traveled since its previous momentum strike.',({e,a,d,t})=>{if(!t)return false;hit(t,d+(e.travelDistance||0)*.3,e,a);e.travelDistance=0;return true;});
ability('timeBomb','Following time bomb','Precision','Attaches a three-second bomb to the enemy; it follows movement and still explodes if the target dies.',({e,a,d,t})=>{if(!t)return false;later(3,()=>blast(e,a,t.x,t.row,d,120));flash(t,'BOMB');return true;});
ability('ricochetShield','Enemy projectile hijack','Precision','Seizes the closest incoming projectile and redirects it toward the opposing side.',({e,a})=>{const p=battle.bullets.filter(p=>!p.dead&&p.side!==e.side&&Math.hypot(p.x-e.x,p.y-rowY(e.row))<a.range)[0];if(!p)return false;p.side=e.side;p.source=e;p.dir=e.side==='plant'?1:-1;p.hit.clear();p.reflected=true;p.a.type='homing';return true;});
ability('comboFinisher','Stored-damage finisher','Precision','Consumes damage accumulated by the caster’s previous attacks over five seconds for one extra hit.',({e,a,d,t})=>{if(!t)return false;const n=e.comboUntil>battle.time?e.comboDamage||0:0;e.comboDamage=0;e.comboUntil=0;hit(t,d+n*.5,e,a);e.comboDamage=0;return true;});

// 131–140: board-wide events.
ability('sunEclipse','Short solar eclipse','Board events','Stops sky sun for six seconds and gives the caster’s side a temporary damage boost.',({e})=>{battle.eclipseUntil=battle.time+6;battle.eclipseSide=e.side;return true;});
ability('timeDilation','Projectile time dilation','Board events','For four seconds, every projectile moves and ages at 35% speed while units act normally.',()=>{battle.dilationUntil=battle.time+4;return true;});
ability('rewindPositions','Position rewind','Board events','Returns living units toward positions recorded three seconds ago, without rewinding health or sun.',()=>{const h=(battle.history||[]).find(h=>h.time>=battle.time-3);if(!h)return false;for(const p of h.positions){const t=alive().find(e=>e.id===p.id);if(!t||t.anchorUntil>battle.time)continue;if(t.side==='zombie'){t.x=p.x;if(compatibleRows(t.u,battle.w).includes(p.row))t.row=p.row;}else if(standable(t.u,p.row,p.col,[t])){t.x=p.x;t.row=p.row;t.col=p.col;}}return true;});
ability('meteorBeacon','Dangerous meteor beacon','Board events','A two-second beacon calls a meteor that damages both sides and leaves a mud tile.',({e,a,d,t})=>{if(!t)return false;const x=t.x,row=t.row,col=tileIndex(t)%battle.w.cols;e.weatherSafeUntil=battle.time+3;later(2,()=>{blast(e,a,x,row,d*2,140,true);setCell(row,col,'mud',8);});return true;});
ability('reinforcementWave','Next-wave reinforcements','Board events','Registers Count copies of the selected template to arrive at the next wave transition.',({e,a})=>{const u=templateFor(e,a);if(!u||e.reinforce)return false;e.reinforce={wave:battle.wave+1,u:clone(u),count:a.count};return true;});
ability('laneTruce','Temporary lane truce','Board events','No unit in the caster’s lane can use offensive attacks for four seconds; movement continues.',({e})=>{battle.truceRows[e.row]=battle.time+4;return true;});
ability('laneFrenzy','Double-speed lane','Board events','Both sides in the caster’s lane recharge their attacks twice as quickly for four seconds.',({e})=>{battle.frenzyRows[e.row]=battle.time+4;return true;});
ability('resourceRain','Free-packet voucher','Board events','Drops a collectible voucher. Clicking it makes the next selected packet free and ignores its recharge.',({e})=>{battle.pickups.push({id:uid(),x:e.x,y:rowY(e.row)-30,until:battle.time+12,type:'voucher'});return true;});
ability('stageShuffle','Adjacent-row shuffle','Board events','Swaps the caster’s lane with the next lane, including tiles, occupants and mower availability.',({e})=>{const r=e.row,n=(r+1)%battle.w.rows;for(let c=0;c<battle.w.cols;c++){const a=r*battle.w.cols+c,b=n*battle.w.cols+c;[battle.w.tiles[a],battle.w.tiles[b]]=[battle.w.tiles[b],battle.w.tiles[a]];}for(const t of alive())if(t.row===r)t.row=n;else if(t.row===n)t.row=r;[battle.mowers[r],battle.mowers[n]]=[battle.mowers[n],battle.mowers[r]];paintBattleTiles();return true;});
ability('tileReset','Ground restoration','Board events','Restores nearby tiles to the level’s initial terrain and clears custom hazards on them.',({e,a})=>{for(let i=0;i<battle.w.tiles.length;i++){const row=Math.floor(i/battle.w.cols),x=cellX(i%battle.w.cols);if(Math.hypot(x-e.x,(row-e.row)*500/battle.w.rows)<a.range){battle.w.tiles[i]=battle.initialTiles[i];delete battle.tileFlags[i];}}battle.zones=battle.zones.filter(z=>Math.hypot(z.x-e.x,(z.row-e.row)*100)>a.range);paintBattleTiles();return true;});

// 141–150: creative utility and recipe interaction.
ability('copyEnemyAbility','Borrow enemy attack','Utility','Copies the nearest enemy’s first basic offensive recipe and uses it once with this caster’s side.',({e,t})=>{const a=t?.u.attacks.find(a=>BASIC_OFFENSE.has(a.type));if(!a)return false;return perform(e,clone(a));});
ability('stealShield','Barrier theft','Utility','Takes all remaining active barrier points from the target and adds them to the caster.',({e,t})=>{if(!t||t.shieldUntil<=battle.time||!t.shieldHP)return false;e.shieldHP=(e.shieldUntil>battle.time?e.shieldHP:0)+t.shieldHP;e.shieldUntil=battle.time+6;t.shieldHP=0;return true;});
ability('mimicLastAttack','Last-action mimic','Utility','Uses the most recently observed basic attack recipe, including one used by the other side.',({e})=>{if(!battle.lastBasicAction)return false;return perform(e,clone(battle.lastBasicAction));});
ability('archiveAttack','Stored attack release','Utility','First activation archives a basic allied attack; the next activation releases it twice and clears the archive.',({e})=>{if(e.archived){const a=e.archived;e.archived=null;perform(e,clone(a));later(.25,()=>{if(!e.dead)perform(e,clone(a));});return true;}const a=e.u.attacks.find(a=>BASIC_OFFENSE.has(a.type));if(!a)return false;e.archived=clone(a);return true;});
ability('mowerEngineer','Mower engineering','Utility','Plants spend Amount sun to restore their lane’s mower; zombies jam that mower for eight seconds.',({e,d})=>{if(e.side==='zombie'){battle.mowerJams[e.row]=battle.time+8;return true;}if(battle.mowers[e.row]||battle.sun<d)return false;battle.sun-=d;battle.mowers[e.row]=true;return true;});
ability('packetLock','Packet jam','Utility','Zombies lock a random seed packet for five seconds; plants remove every active packet jam.',({e})=>{if(e.side==='plant'){battle.packetJams={};return true;}const id=battle.seeds[Math.floor(Math.random()*battle.seeds.length)];if(!id)return false;battle.packetJams[id]=battle.time+5;return true;});
ability('rerollConveyor','Conveyor reroll','Utility','Rerolls all current conveyor packets, or converts one free voucher into a random free packet.',()=>{if(battle.l.conveyor){battle.packets=battle.packets.map(()=>battle.seeds[Math.floor(Math.random()*battle.seeds.length)]);return true;}if(battle.vouchers>0){battle.vouchers--;const id=battle.seeds[Math.floor(Math.random()*battle.seeds.length)];battle.freeSeeds[id]=(battle.freeSeeds[id]||0)+1;return true;}return false;});
ability('upgradeNeighbor','Borrowed secondary recipe','Utility','Gives a neighboring ally the caster’s first basic attack for eight seconds, then removes that extra recipe.',({e,allies})=>{const t=allies.find(t=>t!==e),a=e.u.attacks.find(a=>BASIC_OFFENSE.has(a.type));if(!t||!a||t.u.attacks.length>=80)return false;const copy=clone(a);t.u.attacks.push(copy);t.timers.push(copy.interval);later(8,()=>{const i=t.u.attacks.indexOf(copy);if(i>=0){t.u.attacks.splice(i,1);t.timers.splice(i,1);}});return true;});
ability('recycleUnit','Ally recycling','Utility','Consumes the weakest ally. Plants recover part of its cost; zombies absorb some of its maximum health.',({e,friend,d})=>{if(!friend)return false;if(e.side==='plant')battle.sun+=Math.floor(friend.u.cost*.5+Math.min(d,friend.hp*.1));else{e.maxHp+=Math.min(d,friend.maxHp*.3);e.hp=Math.min(e.maxHp,e.hp+d);}kill(friend,false);return true;});
ability('seedBank','Reserve seed bank','Utility','First activation stores the selected target template. Next activation plants that reserve near the caster for free.',({e,a})=>{if(e.seedReserve){const n=placeNear(e.seedReserve,e.row,Math.max(0,e.col-1));if(n)e.seedReserve=null;return !!n;}const u=templateFor(e,a);if(!u)return false;e.seedReserve=clone(u);return true;});

const BASIC_OFFENSE=new Set(['shot','lob','double','triple','radial','rear','pierce','splash','homing','boomerang','laser','chain','melee','chomp','explode','mine','snipe','drain','crossLaser','globalStrike','cleave','execute','percentHit','scatterShot','mortar','ricochet','splitter']);
function offensive(a){return NEW_ABILITIES[a.type]?.offense===true||BASIC_OFFENSE.has(a.type)||['Projectiles','Targeting','Control','Precision','Reactions'].includes(NEW_ABILITIES[a.type]?.group);}
function ensureNewState(){if(!battle)return;const b=battle;b.tasks??=[];b.newZones??=[];b.tileFlags??={};b.initialTiles??=b.w.tiles.slice();b.truceRows??={};b.frenzyRows??={};b.pickups??=[];b.vouchers??=0;b.freeSeeds??={};b.packetJams??={};b.mowerJams??={};b.fallen??=[];b.history??=[];}
function performNew(e,a,d){const item=NEW_ABILITIES[a.type];if(!item)return null;ensureNewState();const foes=nearFoes(e,a.range),allies=nearAllies(e,a.range);const forced=e.tauntUntil>battle.time&&!e.forcedTarget?.dead?e.forcedTarget:null;if(forced&&foes.includes(forced)){foes.splice(foes.indexOf(forced),1);foes.unshift(forced);}return !!item.run({e,a,d,b:battle,foes,allies,t:foes[0],friend:lowAlly(e,a.range),dir:e.side==='plant'?1:-1});}
function outgoingNewMultiplier(e){const now=battle.time;let bonus=0;if(e.loanUntil>now)bonus+=e.loanDamage||0;bonus+=e._soulShot||0;const base=Math.max(1,e._attackBaseDamage||1);let mult=1+bonus/base;if(battle.eclipseUntil>now&&battle.eclipseSide===e.side)mult*=1.25;if(e.rageSuppressedUntil>now&&e.u.traits.includes('rage')&&e.hp<e.maxHp/2)mult/=1.8;return mult;}
function blockNewAttack(e,a){ensureNewState();const b=battle;if(e.sleepUntil>b.time||e.stoneUntil>b.time||e.cocoonUntil>b.time)return true;if(e.disarmUntil>b.time&&(BASIC_OFFENSE.has(a.type)&&!['melee','chomp','explode','mine','drain'].includes(a.type)||NEW_ABILITIES[a.type]?.group==='Projectiles'))return true;if(b.truceRows[e.row]>b.time&&offensive(a))return true;if(e.confused&&offensive(a)){const t=nearAllies(e,a.range).find(t=>t!==e);e.confused=false;if(t)hit(t,a.damage,e,a);return true;}return false;}
function recordNewAttack(e,a){ensureNewState();e._attackBaseDamage=a.damage;e._soulShot=0;if(offensive(a)&&nearFoes(e,a.range).length){if(e.fatigueUntil>battle.time)e.fatigueDebt=Math.min(8,(e.fatigueDebt||0)+.3);if(e.soulCharge){e._soulShot=e.soulCharge;e.soulCharge=0;}if(e.echoCharge){e.echoCharge=false;const copy={...clone(a),damage:a.damage*.5};later(.15,()=>{if(!e.dead)perform(e,copy);});}}if(BASIC_OFFENSE.has(a.type))battle.lastBasicAction=clone(a);}
function newMovementFactor(e){return e.fearUntil>battle.time&&!(e.anchorUntil>battle.time)?-1:1;}
function newMovementLocked(e){return e.sleepUntil>battle.time||e.stoneUntil>battle.time||e.cocoonUntil>battle.time||e.forcedMotion?.until>battle.time||e.contactCharge?.until>battle.time||e.retreat?.until>battle.time;}
function newRechargeFactor(e){let f=battle.frenzyRows[e.row]>battle.time?2:1;if(e.fatigueUntil>battle.time)f/=1+(e.fatigueDebt||0);return f;}
function adjustNewDamage(e,n,source,a){ensureNewState();const now=battle.time;if(!Number.isFinite(n)||n<=0||e.immuneUntil>now||e.phaseUntil>now&&(now-e.phaseStart)%3<1||!source&&e.weatherSafeUntil>now)return 0;if(e.sleepUntil>now)e.sleepUntil=0;
 if(e.sacrificeGuard&&!e.sacrificeGuard.dead&&!e._redirecting){const guard=e.sacrificeGuard;e.sacrificeGuard=null;guard._redirecting=true;damage(guard,n,source,a);guard._redirecting=false;return 0;}
 if(e.painGuardUntil>now&&e.painGuard&&!e.painGuard.dead&&!e._redirecting){e.painGuard._redirecting=true;damage(e.painGuard,n*.5,source,a);e.painGuard._redirecting=false;n*=.5;}
 if(e.delayPainUntil>now){const debt=n*.5;n*=.5;later(4,()=>{if(!e.dead)pure(e,debt,source);});}
 if(e.stoneUntil>now)n*=.1;if(e.capUntil>now)n=Math.min(n,e.maxHp*.1);
 if(e.adaptUntil>now){const type=a?.type||'environment';e.adaptStacks=e.adaptType===type?Math.min(6,(e.adaptStacks||0)+1):0;e.adaptType=type;n*=1-e.adaptStacks*.1;}
 if(e.polishUntil>now&&e.shieldUntil>now&&e.shieldHP>0)e.hp=Math.min(e.maxHp,e.hp+Math.min(n,e.shieldHP)*.5);
 if(source){e.lastAttacker=source;e.recentPain=(e.recentPain||0)+n;}return n;
}
function afterNewDamage(e,n,source,a){if(n<=0)return;const now=battle.time;if(source){source.comboDamage=source.comboUntil>now?(source.comboDamage||0)+n:n;source.comboUntil=now+5;}
 if(!e._reacting&&e.tetherUntil>now&&e.tether&&!e.tether.dead){e.tether._reacting=true;hit(e.tether,n*.35,source,a);e.tether._reacting=false;}
 if(!e._reacting&&e.conductiveUntil>now&&source){const t=nearAllies(e,130).find(t=>t!==e);if(t){t._reacting=true;hit(t,n*.25,source,a);t._reacting=false;}}
 if(!e._reacting&&e.thornsUntil>now&&source&&!source.dead&&distance(e,source)<85&&!source._reacting){source._reacting=true;hit(source,n*.5,e,null);source._reacting=false;}
 if(e.brood?.charges>0){e.brood.charges--;placeNear(e.brood.u,e.row,Math.max(0,e.col+1));}
}
function beforeNewDeath(e){const now=battle.time;if(e.lastStandArmed&&!e.lastStandSpent){e.lastStandSpent=true;e.lastStandArmed=false;e.hp=1;e.immuneUntil=now+1.5;flash(e,'LAST STAND');return true;}if(e.revenantArmed&&!e.revenantSpent){e.revenantSpent=true;e.revenantArmed=false;e.hp=e.maxHp*.5;e.status.stun=now+2;flash(e,'REBORN');return true;}if(e.phoenix&&!e.phoenixSpent){e.phoenixSpent=true;e.phoenix=false;e.hp=e.maxHp*.35;e.immuneUntil=now+1;flash(e,'PHOENIX');return true;}return false;}
function afterNewDeath(e){ensureNewState();if(!e.expires){battle.fallen.push({u:clone(e.u),side:e.side,row:e.row,col:e.col,used:false});if(battle.fallen.length>100)battle.fallen.shift();}if(e.bounty)battle.sun+=e.bounty;
 if(e.deathNova)blast(e,e.deathNova.a,e.x,e.row,e.deathNova.damage,e.deathNova.range);
 if(e.deathHeal)nearAllies(e,e.deathHeal.range).forEach(t=>t.hp=Math.min(t.maxHp,t.hp+e.deathHeal.amount));
 if(e.deathSun)for(let i=0;i<Math.min(12,e.deathSun.count);i++)addSun(e.x+i*12,rowY(e.row)-30,e.deathSun.amount);
 if(e.splitChildren){const u=cloneUnit(e,{any:true});for(let i=0;i<Math.min(6,e.splitChildren);i++)placeNear(u,Math.max(0,Math.min(battle.w.rows-1,e.row+(i%3)-1)),Math.max(0,e.col));}
 for(const t of alive())if(t.side!==e.side){if(t.rallyUntil>battle.time&&distance(e,t)<t.rallyRange)nearAllies(t,t.rallyRange).forEach(a=>a.timers=a.timers.map(n=>Math.max(0,n-2)));if(t.harvest?.until>battle.time&&distance(e,t)<t.harvest.range)t.soulCharge=(t.soulCharge||0)+t.harvest.amount;}
}
function onNewSpawn(e){ensureNewState();const f=battle.tileFlags[tileIndex(e)];if(f?.fertileUntil>battle.time&&e.side==='plant')battle.sun+=f.value||25;}
function hasFreeSeed(id){return !!battle&&((battle.freeSeeds?.[id]||0)>0||(battle.vouchers||0)>0);}
function consumeFreeSeed(id){if(battle.freeSeeds?.[id]>0){battle.freeSeeds[id]--;return true;}if(battle.vouchers>0){battle.vouchers--;return true;}return false;}
function onNewPurchase(u,cost){ensureNewState();if(cost>0){const rebate=Math.min(cost,battle.purchaseRebate||0);battle.sun+=rebate;battle.purchaseRebate=0;const tax=Math.min(battle.sun,battle.purchaseTax||0);battle.sun-=tax;battle.purchaseTax=0;}}
function moveToAvailable(e,row,col){if(e.anchorUntil>battle.time)return false;if(e.side==='zombie'){if(!compatibleRows(e.u,battle.w).includes(row))return false;e.row=row;e.x=cellX(Math.max(0,Math.min(battle.w.cols-1,col)));return true;}if(!standable(e.u,row,col,[e]))return false;e.row=row;e.col=col;e.x=cellX(col);e.supportId=null;return true;}
function exchangePositions(a,b){if(a.anchorUntil>battle.time||b.anchorUntil>battle.time||a.u.traits.includes('platform')||b.u.traits.includes('platform'))return false;const pa={x:a.x,row:a.row,col:a.col},pb={x:b.x,row:b.row,col:b.col};if(a.side==='plant'&&(!standable(a.u,pb.row,pb.col,[a,b])||!standable(b.u,pa.row,pa.col,[a,b])))return false;if(a.side==='zombie'&&(!compatibleRows(a.u,battle.w).includes(pb.row)||!compatibleRows(b.u,battle.w).includes(pa.row)))return false;Object.assign(a,pb);Object.assign(b,pa);a.supportId=b.supportId=null;return true;}
function connectedTiles(start,type){const seen=new Set(),queue=[start],w=battle.w;while(queue.length){const i=queue.shift();if(seen.has(i)||w.tiles[i]!==type)continue;seen.add(i);const r=Math.floor(i/w.cols),c=i%w.cols;for(const [rr,cc] of [[r-1,c],[r+1,c],[r,c-1],[r,c+1]])if(rr>=0&&rr<w.rows&&cc>=0&&cc<w.cols)queue.push(rr*w.cols+cc);}return seen;}
function forcedStep(e,dx){if(e.anchorUntil>battle.time)return false;const x=Math.max(15,Math.min(930,e.x+dx)),col=Math.max(0,Math.min(battle.w.cols-1,Math.floor(x/900*battle.w.cols)));if(e.side==='plant'&&!standable(e.u,e.row,col,[e]))return false;e.x=x;if(e.side==='plant')e.col=col;return true;}
function tickNewEntity(e,dt){const b=battle,now=b.time;e.travelDistance=(e.travelDistance||0)+(e.previousPosition?Math.hypot(e.x-e.previousPosition.x,(e.row-e.previousPosition.row)*500/b.w.rows):0);e.previousPosition={x:e.x,row:e.row};if(e.expires&&now>=e.expires){kill(e,false);return;}
 if(e.dividendWave&&b.wave>=e.dividendWave){b.sun+=e.dividendAmount;e.dividendWave=0;}
 if(e.reinforce&&b.wave>=e.reinforce.wave){const f=e.reinforce;e.reinforce=null;for(let i=0;i<Math.min(12,f.count);i++)placeNear(f.u,Math.min(b.w.rows-1,e.row+i%2),Math.max(0,e.col));}
 if(e.erosion?.until>now)nearFoes(e,e.erosion.range).forEach(t=>{t.maxHp=Math.max(1,t.maxHp-e.erosion.amount*dt);t.hp=Math.min(t.hp,t.maxHp);});
 if(e.forcedMotion?.until>now)forcedStep(e,e.forcedMotion.vx*dt);
 if(e.retreat?.until>now){forcedStep(e,e.retreat.vx*dt);e.hp=Math.min(e.maxHp,e.hp+e.retreat.heal*dt);}
 if(e.contactCharge?.until>now){const f=e.contactCharge,t=nearFoes(e,75).find(t=>t.row===e.row);if(t){hit(t,f.damage,e,f.a);e.contactCharge=null;e.status.stun=now+.5;}else forcedStep(e,f.vx*dt);}
 if(e.orbitAnchor?.until>now&&e.orbitAnchor.next<=now&&!e.orbitAnchor.target.dead){const f=e.orbitAnchor;f.next=now+1;const rows=[f.target.row-1,f.target.row+1,f.target.row];for(const row of rows)if(row!==e.row&&moveToAvailable(e,row,Math.max(0,f.target.col-1)))break;}
 const flag=b.tileFlags[tileIndex(e)];if(flag){if(flag.quarantineUntil>now)e.status.silence=now+.15;if(flag.brittleUntil>now&&e.side==='zombie'&&!e.u.traits.includes('flying')){e.status.stun=now+1.2;flag.brittleUntil=0;b.w.tiles[tileIndex(e)]='grass';paintBattleTiles();}if(flag.gate?.until>now&&flag.gate.side!==e.side){for(const row of [e.row+1,e.row-1])if(reposition(e,row,Math.max(0,e.col)))break;delete flag.gate;}if(flag.mine&&flag.mine.until>now&&flag.mine.side!==e.side&&!e.u.traits.includes('flying')){const chain=flag.mine.chain;for(const [key,f] of Object.entries(b.tileFlags))if(f.mine?.chain===chain){const i=+key,m=f.mine;delete f.mine;blast(m.source,m.a,cellX(i%b.w.cols),Math.floor(i/b.w.cols),m.damage,95);}}}
}
function tickNewWorld(dt){ensureNewState();const b=battle,now=b.time;if(b.weatherOverrides){b.weatherOverrides=b.weatherOverrides.filter(w=>w.until>now);b.weather={...(b.weatherOverrides.at(-1)||b.weatherBase)};if(!b.weatherOverrides.length){delete b.weatherOverrides;delete b.weatherBase;}}const ready=b.tasks.filter(t=>t.at<=now);b.tasks=b.tasks.filter(t=>t.at>now);for(const task of ready)task.fn();if(now>=(b.nextHistory||0)){b.nextHistory=now+.5;b.history.push({time:now,positions:alive().map(e=>({id:e.id,x:e.x,row:e.row,col:e.col}))});b.history=b.history.filter(h=>h.time>=now-4);}
 for(const z of b.newZones){if(z.until<=now)continue;const ts=alive().filter(t=>Math.hypot(t.x-z.x,(t.row-z.row)*500/b.w.rows)<=z.radius);if(z.type==='vortex')ts.filter(t=>t.side!==z.source.side&&!(t.anchorUntil>now)).forEach(t=>{t.x+=(z.x-t.x)*Math.min(1,dt*2);});if(z.type==='sprinkler')ts.forEach(t=>{delete t.status.burn;if(t.side===z.source.side)t.hp=Math.min(t.maxHp,t.hp+z.amount*dt);});}
 b.newZones=b.newZones.filter(z=>z.until>now);b.pickups=b.pickups.filter(p=>p.until>now);
 for(const [key,f] of Object.entries(b.tileFlags))if(f.sunWellUntil>now){const row=Math.floor(+key/b.w.cols),x=cellX(+key%b.w.cols);b.suns.filter(s=>!s.doubled&&Math.hypot(s.x-x,s.y-rowY(row))<100).forEach(s=>{s.value*=2;s.doubled=true;});}
 for(const e of alive())if(e.netUntil>now&&e.netCharges>0)for(const p of b.bullets)if(!p.dead&&p.side!==e.side&&Math.hypot(p.x-e.x,p.y-rowY(e.row)+25)<100&&e.netCharges>0){p.dead=true;e.netCharges--;flash(e,'CAUGHT');}
}
function customNewMotion(p,dt,targets){if(!p.newKind)return false;const b=battle,t=b.time;
 if(p.newKind==='orbit'&&p.age<1){p.x=p.source.x+Math.cos(p.orbitAngle+p.age*6)*55;p.y=rowY(p.source.row)-40+Math.sin(p.orbitAngle+p.age*6)*50;return true;}
 if(p.newKind==='orbit'){p.a.type='homing';return false;}
 if(p.newKind==='returnHeal'&&p.returnPhase){if(p.source.dead){p.dead=true;return true;}const dx=p.source.x-p.x,dy=rowY(p.source.row)-25-p.y,dist=Math.hypot(dx,dy);if(dist<25){p.source.hp=Math.min(p.source.maxHp,p.source.hp+p.damage);p.dead=true;}else{p.x+=dx/dist*380*dt;p.y+=dy/dist*380*dt;}return true;}
 if(p.newKind==='gravity')targets.filter(t=>Math.hypot(t.x-p.x,rowY(t.row)-25-p.y)<90&&!(t.anchorUntil>b.time)).forEach(t=>t.x+=(p.x-t.x)*dt*.9);
 if(p.newKind==='weave'){p.x+=p.dir*p.speed*dt;p.y=p.startY+Math.sin(p.age*7)*95;return true;}
 if(p.newKind==='accelerate'){p.speed=Math.min(900,p.speed+400*dt);return false;}
 if(p.newKind==='relay'&&p.relay){if(p.relay.dead){p.relay=null;return false;}const dx=p.relay.x-p.x,dy=rowY(p.relay.row)-25-p.y,dist=Math.hypot(dx,dy);if(dist<25){p.x=p.relay.x+p.dir*25;p.y=rowY(p.relay.row)-25;p.row=p.relay.row;p.damage*=1.5;p.relay=null;p.speed=420;}else{p.x+=dx/dist*360*dt;p.y+=dy/dist*360*dt;}return true;}
 if(p.newKind==='cluster'&&p.age>=.8){blast(p.source,p.ability,p.x,Math.max(0,Math.min(b.w.rows-1,Math.floor(p.y/500*b.w.rows))),p.damage,130);p.dead=true;return true;}
 if(p.newKind==='trapSeed'){const q=Math.min(1,p.age/p.flight);p.x=p.startX+(p.destination.x-p.startX)*q;p.y=p.startY+(rowY(p.destination.row)-25-p.startY)*q-Math.sin(q*Math.PI)*100;if(q===1){zone(p.source,'trap',p.destination.x,p.destination.row,p.damage,p.ability);p.dead=true;}return true;}
 if(p.newKind==='snowball'){p.damage+=12*dt;p.visualSize=Math.min(7,2.3+p.age);}
 return false;
}
function handleNewBulletHit(p,t){if(!p.newKind)return false;if(p.dead||p.age<0)return true;if(p.newKind==='orbit'&&p.age<1||p.newKind==='relay'&&p.relay||p.newKind==='cluster'||p.newKind==='trapSeed'||p.newKind==='returnHeal'&&p.returnPhase)return true;
 if(t.frontShieldUntil>battle.time&&p.dir===(t.side==='plant'?-1:1)){p.dead=true;flash(t,'BLOCK');return true;}
 if(p.newKind==='returnHeal'){p.hit.add(t.id);hit(t,p.damage,p.source,p.ability);p.returnPhase=true;return true;}
 if(p.newKind==='drill'){p.hit.add(t.id);hit(t,p.damage,p.source,p.ability);p.damage*=.75;p.speed*=.8;if(p.damage<1||p.speed<25)p.dead=true;return true;}
 if(p.newKind==='charge'||p.newKind==='accelerate'){p.hit.add(t.id);hit(t,p.damage*(1+(p.newKind==='charge'?p.age:p.speed/600)),p.source,p.ability);p.dead=true;return true;}
 if(p.newKind==='snowball'){p.hit.add(t.id);blast(p.source,p.ability,t.x,t.row,p.damage,65+p.age*20);p.dead=true;return true;}
 return false;
}
function renderNewWorld(){ensureNewState();if(!domMaps.newzone)domMaps.newzone=new Map();syncNodes(domMaps.newzone,battle.newZones,z=>{const el=document.createElement('div');el.className='hazardZone';return el;},(el,z)=>{el.style.left=z.x/9+'%';el.style.top=(rowY(z.row)-25)/5+'%';el.style.width=z.radius*2/9+'%';el.style.height=z.radius*2/5+'%';el.style.background=z.type==='vortex'?'#8c76e855':'#75dff755';el.textContent=z.type==='vortex'?'◉':'≋';});
 if(!domMaps.pickup)domMaps.pickup=new Map();syncNodes(domMaps.pickup,battle.pickups,p=>{const el=document.createElement('button');el.className='sun voucher';el.textContent='FREE';el.onclick=event=>{event.stopPropagation();if(battle.paused||battle.ended||battle.dialogOpen)return;battle.vouchers++;battle.pickups=battle.pickups.filter(x=>x!==p);el.remove();renderSeeds();};return el;},(el,p)=>{el.style.left=p.x/9+'%';el.style.top=p.y/5+'%';});
 if($('#weatherCanvas'))$('#weatherCanvas').style.backgroundColor=battle.eclipseUntil>battle.time?'#03153c66':'transparent';
 for(const p of battle.bullets)if(p.visualSize){const el=domMaps.bullet.get(p.id);if(el){el.style.width=p.visualSize+'%';el.style.height=p.visualSize*1.8+'%';}}
}

function enhanceAbilityPicker(u,root){const section=root.querySelector('.abilitySection');if(!section)return;const tools=document.createElement('div');tools.innerHTML=`<div class="abilityTools"><label>Search 310 abilities<input id="abilitySearch" placeholder="e.g. terrain, revive, reflect…"></label><label>Category<select id="abilityCategory"><option value="">All categories</option>${[...new Set(Object.values(NEW_ABILITIES).filter(a=>!a.side||a.side===u.side).map(a=>a.group))].sort().map(g=>`<option>${g}</option>`).join('')}<option>Original 60</option></select></label></div><div class="catalogCount" id="catalogCount"></div><div class="abilityCatalog" id="abilityCatalog"></div>`;section.insertBefore(tools,section.querySelector('#attacks'));$('#abilitySearch').value=selected.abilityQuery||'';$('#abilityCategory').value=selected.abilityGroup||'';const filter=()=>{const query=$('#abilitySearch').value.toLowerCase(),group=$('#abilityCategory').value;selected.abilityQuery=$('#abilitySearch').value;selected.abilityGroup=group;const items=Object.entries(ATTACKS).filter(([id,name])=>{const item=NEW_ABILITIES[id],category=item?.group||'Original 60',help=item?.help||BEHAVIOR_HELP[id]||'';return (!item?.side||item.side===u.side)&&(!group||group===category)&&(!query||(name+' '+category+' '+help).toLowerCase().includes(query));});$('#catalogCount').textContent=`${items.length} abilities found · Click one to add a recipe`;
 $('#abilityCatalog').innerHTML=items.map(([id,name])=>`<button data-add-ability="${id}" title="${esc(NEW_ABILITIES[id]?.help||BEHAVIOR_HELP[id]||name)}">${esc(name)}<small>${NEW_ABILITIES[id]?.group||'Original 60'}</small></button>`).join('');$$('[data-add-ability]').forEach(b=>b.onclick=()=>{if(u.attacks.length>=80)return toast('A unit can stack up to 80 recipes.');u.attacks.push(attack(b.dataset.addAbility));save();render();});};$('#abilitySearch').oninput=filter;$('#abilityCategory').onchange=filter;filter();}
function buildSeedTray(){const tray=document.createElement('div');tray.className='seedTray';const seed=$('#seeds'),sun=$('.sunCount');seed.parentNode.insertBefore(tray,seed);tray.append(seed,sun);}
if(Object.keys(NEW_ABILITIES).length!==150)throw Error('The extension must define exactly 150 abilities.');
/* CREATOR_EXPANSION */
Object.assign(ATTACKS,Object.fromEntries(Object.entries(NEW_ABILITIES).map(([id,x])=>[id,x.name])));
Object.assign(BEHAVIOR_HELP,Object.fromEntries(Object.entries(NEW_ABILITIES).map(([id,x])=>[id,x.help])));
function buildLawnTexture(w){
 const c=document.createElement('canvas');c.width=900;c.height=500;const g=c.getContext('2d');if(!g)return;
 let seed=31819;const rnd=()=>((seed=Math.imul(seed,1664525)+1013904223>>>0)/4294967296);
 g.fillStyle='#30a62c';g.fillRect(0,0,900,500);
 for(let r=0;r<w.rows;r++)for(let col=0;col<w.cols;col++){g.fillStyle=(r+col)%2?'#46bc3866':'#168d2d33';g.fillRect(col*900/w.cols,r*500/w.rows,900/w.cols,500/w.rows);}
 for(let i=0;i<1100;i++){const x=rnd()*900,y=rnd()*500;g.fillStyle=['#0d92251b','#67d34727','#188d291c'][i%3];g.beginPath();g.ellipse(x,y,3+rnd()*14,2+rnd()*8,0,0,7);g.fill();}
 for(let i=0;i<19000;i++){const x=rnd()*900,y=rnd()*500,h=1+rnd()*5;g.strokeStyle=['#7cda4466','#0c852c66','#52c83d77','#a8e76c44'][i%4];g.lineWidth=.5+rnd();g.beginPath();g.moveTo(x,y);g.lineTo(x-1+rnd()*3,y-h);g.stroke();}
 for(let i=0;i<160;i++){const x=rnd()*900,y=rnd()*500;g.fillStyle=i%5===0?'#d2eb4a99':'#84d35755';g.beginPath();g.ellipse(x,y,1+rnd()*2,1+rnd()*2,0,0,7);g.fill();}
 $('#board').style.backgroundImage=`url("${c.toDataURL('image/png')}")`;$('#board').style.backgroundSize='100% 100%';$('#board').classList.add('proceduralLawn');
}

function newBulletCanCollide(p){return !p.dead&&!(p.newKind==='orbit'&&p.age<1||p.newKind==='relay'&&p.relay||p.newKind==='cluster'||p.newKind==='trapSeed'||p.newKind==='returnHeal'&&p.returnPhase);}
